using System.IdentityModel.Tokens.Jwt;
using System.Text.Json;
using LifeVerse.Api.Data;
using LifeVerse.Api.Modules.Land;
using Microsoft.EntityFrameworkCore;

namespace LifeVerse.Api.Modules.Worlds;

public sealed record ParcelRequest(string Name, string? Description, double MinX, double MinZ, double MaxX, double MaxZ, int MaxObjects = 1000, string? PermissionsJson = null, string? EnvironmentJson = null, float SpawnX = 0, float SpawnY = 1, float SpawnZ = 0);
public sealed record ParcelUpdateRequest(string? Name, string? Description, int? MaxObjects, string? PermissionsJson, string? EnvironmentJson, float? SpawnX, float? SpawnY, float? SpawnZ, int ExpectedRevision);
public sealed record ParcelTerrainRequest(string Operation, string PayloadJson, int ExpectedRevision);

public static class ParcelEndpoints
{
    public static IEndpointRouteBuilder MapParcelEndpoints(this IEndpointRouteBuilder endpoints)
    {
        var group = endpoints.MapGroup("/api/v1/worlds/islands/{islandId:guid}/parcels").WithTags("Parcels").RequireAuthorization();
        group.MapGet("", ListAsync); group.MapPost("", CreateAsync); group.MapGet("/{parcelId:guid}", GetAsync); group.MapPatch("/{parcelId:guid}", UpdateAsync); group.MapPost("/{parcelId:guid}/terrain", TerrainAsync); group.MapGet("/{parcelId:guid}/changes", ChangesAsync); group.MapDelete("/{parcelId:guid}", DeleteAsync);
        return endpoints;
    }
    private static async Task<IResult> ListAsync(Guid islandId, HttpContext context, LifeVerseDbContext db, CancellationToken ct) { if (!User(context, out var user)) return Results.Unauthorized(); var island = await db.Islands.AsNoTracking().SingleOrDefaultAsync(x => x.Id == islandId && x.DeletedAt == null, ct); if (island is null) return Results.NotFound(); if (!await CanIslandAsync(db, island, user, "enter", ct)) return Results.Forbid(); return Results.Ok(await db.IslandParcels.AsNoTracking().Where(x => x.IslandId == islandId && x.DeletedAt == null).OrderBy(x => x.Name).ToListAsync(ct)); }
    private static async Task<IResult> GetAsync(Guid islandId, Guid parcelId, HttpContext context, LifeVerseDbContext db, CancellationToken ct) { if (!User(context, out var user)) return Results.Unauthorized(); var parcel = await db.IslandParcels.AsNoTracking().SingleOrDefaultAsync(x => x.Id == parcelId && x.IslandId == islandId && x.DeletedAt == null, ct); return parcel is null ? Results.NotFound() : await CanIslandAsync(db, await db.Islands.AsNoTracking().SingleAsync(x => x.Id == islandId, ct), user, "enter", ct) ? Results.Ok(parcel) : Results.Forbid(); }
    private static async Task<IResult> CreateAsync(Guid islandId, ParcelRequest request, HttpContext context, LifeVerseDbContext db, TimeProvider clock, CancellationToken ct)
    {
        if (!User(context, out var user)) return Results.Unauthorized();
        var island = await db.Islands.SingleOrDefaultAsync(x => x.Id == islandId && x.DeletedAt == null, ct); if (island is null) return Results.NotFound();
        if (island.OwnerUserId != user && !await CanIslandAsync(db, island, user, "admin", ct)) return Results.Forbid();
        if (!ValidBounds(island, request.MinX, request.MinZ, request.MaxX, request.MaxZ)) return Results.BadRequest(new { error = "Invalid parcel bounds, name or object limit." });
        // the rectangle becomes cells of the territorial grid; the grid is what keeps two parcels from overlapping
        var result = await LandService.ClaimAsync(db, island, user, request.Name, request.Description, LandGrid.CellsInRect(request.MinX, request.MinZ, request.MaxX, request.MaxZ), request.MaxObjects, request.PermissionsJson, request.EnvironmentJson, request.SpawnX, request.SpawnY, request.SpawnZ, clock, ct);
        if (result.Parcel is null) return result.Error is "overlap" or "name_taken" ? Results.Conflict(new { error = result.Error, parcelId = result.ConflictParcelId }) : Results.BadRequest(new { error = "Invalid parcel bounds, name or object limit." });
        return Results.Created($"/api/v1/worlds/islands/{islandId}/parcels/{result.Parcel.Id}", result.Parcel);
    }
    private static async Task<IResult> UpdateAsync(Guid islandId, Guid parcelId, ParcelUpdateRequest request, HttpContext context, LifeVerseDbContext db, TimeProvider clock, CancellationToken ct) { if (!User(context, out var user)) return Results.Unauthorized(); var parcel = await db.IslandParcels.SingleOrDefaultAsync(x => x.Id == parcelId && x.IslandId == islandId && x.DeletedAt == null, ct); if (parcel is null) return Results.NotFound(); if (parcel.OwnerUserId != user && !await CanIslandAsync(db, await db.Islands.SingleAsync(x => x.Id == islandId, ct), user, "admin", ct)) return Results.Forbid(); if (request.ExpectedRevision != parcel.Revision) return Results.Conflict(new { currentRevision = parcel.Revision }); if (request.Name is not null) parcel.Name = request.Name.Trim()[..Math.Min(120, request.Name.Trim().Length)]; if (request.Description is not null) parcel.Description = request.Description[..Math.Min(4000, request.Description.Length)]; if (request.MaxObjects is not null && request.MaxObjects is >= 1 and <= 100000) parcel.MaxObjects = request.MaxObjects.Value; if (request.PermissionsJson is not null) parcel.PermissionsJson = ValidJson(request.PermissionsJson, parcel.PermissionsJson); if (request.EnvironmentJson is not null) parcel.EnvironmentJson = ValidJson(request.EnvironmentJson, parcel.EnvironmentJson); parcel.SpawnX = request.SpawnX ?? parcel.SpawnX; parcel.SpawnY = request.SpawnY ?? parcel.SpawnY; parcel.SpawnZ = request.SpawnZ ?? parcel.SpawnZ; parcel.Revision++; parcel.UpdatedAt = clock.GetUtcNow(); db.ParcelChanges.Add(new ParcelChange { Id = Guid.NewGuid(), ParcelId = parcel.Id, ActorUserId = user, Operation = "update", PayloadJson = "{}", Revision = parcel.Revision, CreatedAt = parcel.UpdatedAt }); await db.SaveChangesAsync(ct); return Results.Ok(parcel); }
    private static async Task<IResult> TerrainAsync(Guid islandId, Guid parcelId, ParcelTerrainRequest request, HttpContext context, LifeVerseDbContext db, TimeProvider clock, CancellationToken ct) { if (!User(context, out var user)) return Results.Unauthorized(); var parcel = await db.IslandParcels.SingleOrDefaultAsync(x => x.Id == parcelId && x.IslandId == islandId && x.DeletedAt == null, ct); if (parcel is null) return Results.NotFound(); if (parcel.OwnerUserId != user && !await CanIslandAsync(db, await db.Islands.SingleAsync(x => x.Id == islandId, ct), user, "edit_terrain", ct)) return Results.Forbid(); if (request.ExpectedRevision != parcel.Revision || request.PayloadJson.Length > 1_000_000 || !JsonValid(request.PayloadJson) || request.Operation.Length is < 1 or > 48) return Results.Conflict(new { currentRevision = parcel.Revision }); parcel.Revision++; parcel.UpdatedAt = clock.GetUtcNow(); db.ParcelChanges.Add(new ParcelChange { Id = Guid.NewGuid(), ParcelId = parcel.Id, ActorUserId = user, Operation = request.Operation, PayloadJson = request.PayloadJson, Revision = parcel.Revision, CreatedAt = parcel.UpdatedAt }); await db.SaveChangesAsync(ct); return Results.Ok(new { parcelId, revision = parcel.Revision, operation = request.Operation }); }
    private static async Task<IResult> ChangesAsync(Guid islandId, Guid parcelId, HttpContext context, LifeVerseDbContext db, CancellationToken ct) { if (!User(context, out var user)) return Results.Unauthorized(); if (!await db.IslandParcels.AnyAsync(x => x.Id == parcelId && x.IslandId == islandId && x.DeletedAt == null, ct)) return Results.NotFound(); if (!await CanIslandAsync(db, await db.Islands.AsNoTracking().SingleAsync(x => x.Id == islandId, ct), user, "enter", ct)) return Results.Forbid(); return Results.Ok(await db.ParcelChanges.AsNoTracking().Where(x => x.ParcelId == parcelId).OrderByDescending(x => x.CreatedAt).Take(100).ToListAsync(ct)); }
    private static async Task<IResult> DeleteAsync(Guid islandId, Guid parcelId, HttpContext context, LifeVerseDbContext db, TimeProvider clock, CancellationToken ct) { if (!User(context, out var user)) return Results.Unauthorized(); var parcel = await db.IslandParcels.SingleOrDefaultAsync(x => x.Id == parcelId && x.IslandId == islandId && x.DeletedAt == null, ct); if (parcel is null) return Results.NotFound(); if (parcel.OwnerUserId != user) return Results.Forbid(); parcel.DeletedAt = clock.GetUtcNow(); await db.SaveChangesAsync(ct); await LandService.ReleaseAsync(db, parcel.Id, ct); return Results.NoContent(); }
    private static bool ValidBounds(Island island, double minX, double minZ, double maxX, double maxZ) => minX < maxX && minZ < maxZ && minX >= -island.Size / 2d && maxX <= island.Size / 2d && minZ >= -island.Size / 2d && maxZ <= island.Size / 2d;
    private static string ValidJson(string? value, string fallback) { if (string.IsNullOrWhiteSpace(value)) return fallback; try { using var doc = JsonDocument.Parse(value); return doc.RootElement.ValueKind == JsonValueKind.Object ? value : fallback; } catch { return fallback; } }
    private static bool JsonValid(string value) { try { using var doc = JsonDocument.Parse(value); return doc.RootElement.ValueKind is JsonValueKind.Object or JsonValueKind.Array; } catch { return false; } }
    private static async Task<bool> CanIslandAsync(LifeVerseDbContext db, Island island, Guid user, string permission, CancellationToken ct) => island.OwnerUserId == user || await db.IslandPermissions.AnyAsync(x => x.IslandId == island.Id && x.UserId == user && x.RevokedAt == null && (x.Permission == permission || x.Permission == "admin"), ct);
    private static bool User(HttpContext context, out Guid user) => Guid.TryParse(context.User.FindFirst(JwtRegisteredClaimNames.Sub)?.Value, out user);
}
